use clap::{Parser, Subcommand};
use std::path::PathBuf;
use std::fs::Metadata;
use std::collections::{HashMap, HashSet};
use walkdir::WalkDir;
use colored::Colorize;
use std::cmp::Ordering;

#[derive(Parser)]
#[command(name = "dua")]
#[command(about = "A tool to learn about disk usage, fast!", long_about = None)]
#[command(version = "2.32.2")]
struct Cli {
    #[command(subcommand)]
    command: Option<Commands>,

