    apparent_size: bool,

    /// Count hard-linked files each time they are seen
    #[arg(short = 'l', long)]
    count_hard_links: bool,

    /// If set, we will not cross filesystems or traverse mount points
    #[arg(short = 'x', long)]
    stay_on_filesystem: bool,

    /// One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.
    #[arg(short = 'i', long, default_values = vec!["/proc", "/dev", "/sys", "/run"])]
    ignore_dirs: Vec<PathBuf>,

    /// Write a log file with debug information, including panics
    #[arg(long)]
    log_file: Option<PathBuf>,
}

#[derive(Subcommand)]
enum Commands {
    /// Launch the terminal user interface
    #[command(alias = "i")]
    Interactive {
        /// One or more input files or directories
        #[arg(value_name = "INPUT")]
        input: Vec<PathBuf>,
    },

    /// Aggregate the consumed space of one or more directories or files
    #[command(alias = "a")]
    Aggregate {
        /// One or more input files or directories
        #[arg(value_name = "INPUT")]
        input: Vec<PathBuf>,
    },

    /// Generate shell completions
    Completions {
        /// The shell to generate a completions-script for
        shell: String,
    },
}

fn format_bytes(bytes: u64, format: &str) -> String {
    match format {
        "bytes" => format!("{:>11} b", bytes),
        "binary" => {
            if bytes == 0 {
                "      0   B".to_string()
            } else if bytes < 1024 {
                format!("{:>11}   B", bytes)
            } else if bytes < 1024 * 1024 {
                let kib = bytes as f64 / 1024.0;
                format!("{:>9.2} KiB", kib)
            } else if bytes < 1024 * 1024 * 1024 {
                let mib = bytes as f64 / (1024.0 * 1024.0);
                format!("{:>9.2} MiB", mib)
            } else if bytes < 1024u64 * 1024 * 1024 * 1024 {
                let gib = bytes as f64 / (1024.0 * 1024.0 * 1024.0);
                format!("{:>9.2} GiB", gib)
            } else {
                let tib = bytes as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0);
                format!("{:>9.2} TiB", tib)
            }
        },
        "metric" => {
            if bytes == 0 {
                "     0  B".to_string()
            } else if bytes < 1000 {
                format!("{:>9}  B", bytes)
            } else if bytes < 1000 * 1000 {
                let kb = bytes as f64 / 1000.0;
                format!("{:>7.2} KB", kb)
            } else if bytes < 1000 * 1000 * 1000 {
                let mb = bytes as f64 / (1000.0 * 1000.0);
                format!("{:>7.2} MB", mb)
            } else if bytes < 1000u64 * 1000 * 1000 * 1000 {
                let gb = bytes as f64 / (1000.0 * 1000.0 * 1000.0);
                format!("{:>7.2} GB", gb)
            } else {
                let tb = bytes as f64 / (1000.0 * 1000.0 * 1000.0 * 1000.0);
                format!("{:>7.2} TB", tb)
            }
        },
        "mb" => {
            let mb = bytes as f64 / (1000.0 * 1000.0);
            format!("{:>13.2} MB", mb)
        },
        "mib" => {
            let mib = bytes as f64 / (1024.0 * 1024.0);
            format!("{:>13.2} MiB", mib)
        },
        "gb" => {
            let gb = bytes as f64 / (1000.0 * 1000.0 * 1000.0);
            format!("{:>13.2} GB", gb)
        },
        "gib" => {
            let gib = bytes as f64 / (1024.0 * 1024.0 * 1024.0);
            format!("{:>13.2} GiB", gib)
        },
        _ => format!("{}", bytes),
    }
}

fn get_size(metadata: &Metadata, apparent_size: bool) -> u64 {
    if apparent_size {
        metadata.len()
    } else {
        metadata.blocks() as u64 * 512
    }
}

fn aggregate_path(
    path: &PathBuf,
    apparent_size: bool,
    count_hard_links: bool,
    ignore_dirs: &HashSet<PathBuf>,
    stay_on_filesystem: bool,
) -> (u64, Vec<(String, u64)>) {
    let mut entries = Vec::new();
    let mut total = 0u64;
    let mut seen_inodes = HashMap::new();
    let mut root_device = None;

    if let Ok(metadata) = std::fs::metadata(path) {
        if metadata.is_file() {
            let size = get_size(&metadata, apparent_size);
            let name = path.file_name()
                .and_then(|n| n.to_str())
                .unwrap_or("")
                .to_string();
            return (size, vec![(name, size)]);
        }
    }

    for entry in WalkDir::new(path)
        .into_iter()
        .filter_map(Result::ok)
    {
        let path_buf = entry.path().to_path_buf();

        // Check if we should ignore this directory
        if entry.depth() > 0 && entry.path().is_dir() {
            let canonical = match path_buf.canonicalize() {
                Ok(p) => p,
                Err(_) => continue,
            };

            if ignore_dirs.contains(&canonical) {
                continue;
            }
        }

        if let Ok(metadata) = entry.metadata() {
            // Handle filesystem boundary
            if stay_on_filesystem && entry.depth() > 0 {
                if root_device.is_none() {
                    if let Ok(root_meta) = std::fs::metadata(path) {
                        root_device = Some((root_meta.dev(), root_meta.ino()));
                    }
                }
                if let Some((root_dev, _)) = root_device {
                    if metadata.dev() != root_dev {
                        continue;
                    }
                }
            }

            let mut size = get_size(&metadata, apparent_size);

            // Handle hard links
            if !count_hard_links && metadata.nlink() > 1 {
                let inode_key = (metadata.dev(), metadata.ino());
                if let Some(&prev_size) = seen_inodes.get(&inode_key) {
                    size = 0;
                } else {
                    seen_inodes.insert(inode_key, size);
                }
            } else if !count_hard_links {
                let inode_key = (metadata.dev(), metadata.ino());
                seen_inodes.insert(inode_key, size);
            }

            total += size;

            if entry.depth() == 1 {
                let name = path_buf.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("")
                    .to_string();
                entries.push((name, size));
            }
        }
    }

    // Sort by size in descending order
    entries.sort_by(|a, b| {
        match b.1.cmp(&a.1) {
            Ordering::Equal => a.0.cmp(&b.0),
            other => other,
        }
    });

    (total, entries)
}

fn run_aggregate(cli: &Cli) -> anyhow::Result<()> {
    let inputs = if cli.input.is_empty() {
        // Get all entries in current directory
        let mut entries = Vec::new();
        if let Ok(dir) = std::fs::read_dir(".") {
            for entry in dir.filter_map(Result::ok) {
                entries.push(entry.path());
            }
        }
        entries
    } else {
        cli.input.clone()
    };

    let mut ignore_dirs_set = HashSet::new();
    for dir in &cli.ignore_dirs {
        if let Ok(canonical) = dir.canonicalize() {
            ignore_dirs_set.insert(canonical);
        }
    }

    if inputs.len() == 1 {
        let path = &inputs[0];
        let (total, entries) = aggregate_path(
            path,
            cli.apparent_size,
            cli.count_hard_links,
            &ignore_dirs_set,
            cli.stay_on_filesystem,
        );

        for (name, size) in entries {
            let formatted = format_bytes(size, &cli.format);
            println!("{} {}", formatted.green(), name);
        }

        let total_formatted = format_bytes(total, &cli.format);
        println!("{} {}", total_formatted.green(), "total");
    } else {
        // Handle multiple inputs
        let mut results = Vec::new();
        for input_path in &inputs {
            let (_, entries) = aggregate_path(
                input_path,
                cli.apparent_size,
                cli.count_hard_links,
                &ignore_dirs_set,
                cli.stay_on_filesystem,
            );

            for (_, size) in entries {
                results.push((input_path.display().to_string(), size));
            }
        }

        results.sort_by(|a, b| {
            match b.1.cmp(&a.1) {
                Ordering::Equal => a.0.cmp(&b.0),
                other => other,
            }
        });

        let mut total = 0u64;
        for (name, size) in &results {
            let formatted = format_bytes(*size, &cli.format);
            println!("{} {}", formatted.green(), name);
            total += size;
        }

        let total_formatted = format_bytes(total, &cli.format);
        println!("{} {}", total_formatted.green(), "total");
    }

    Ok(())
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Some(Commands::Interactive { input: _ }) => {
            eprintln!("Error: Interactive mode requires a connected terminal");
            std::process::exit(1);
        },
        Some(Commands::Aggregate { input: _ }) => {
            run_aggregate(&cli)?;
        },
        Some(Commands::Completions { shell }) => {
            generate_completions(shell)?;
        },
        None => {
            run_aggregate(&cli)?;
        },
    }

    Ok(())
}

fn generate_completions(shell: &str) -> anyhow::Result<()> {
    match shell {
        "bash" => {
            println!("_dua() {{\n    local i cur prev opts cmd\n    COMPREPLY=()\n    if [[ \"${{BASH_VERSINFO[0]}}\" -ge 4 ]]; then\n        cur=\"$2\"\n    else\n        cur=\"${{COMP_WORDS[COMP_CWORD]}}\"\n    fi\n    prev=\"$3\"\n    cmd=\"\"\n    opts=\"\"\n\n    for i in \"${{COMP_WORDS[@]:0:COMP_CWORD}}\"\n    do\n        case \"${{cmd}},${{i}}\" in\n            \",\\$1\")\n                cmd=\"dua\"\n                ;;\n            dua,a)\n                cmd=\"dua__aggregate\"\n                ;;\n            dua,a*)\n                cmd=\"dua__aggregate\"\n                ;;\n            dua,aggregate)\n                cmd=\"dua__aggregate\"\n                ;;\n            dua,c)\n                cmd=\"dua__completions\"\n                ;;\n            dua,c*)\n                cmd=\"dua__completions\"\n                ;;\n            dua,completions)\n                cmd=\"dua__completions\"\n                ;;\n            dua,help)\n                cmd=\"dua__help\"\n                ;;\n            dua,i)\n                cmd=\"dua__interactive\"\n                ;;\n            dua,i*)\n                cmd=\"dua__interactive\"\n                ;;\n            dua,interactive)\n                cmd=\"dua__interactive\"\n                ;;\n            dua,interactive)\n                cmd=\"dua__interactive\"\n                ;;\n            *)\n                ;;\n        esac\n    done\n\n    case \"${{cmd}}\" in\n        dua)\n            opts=\"-t -f -A -l -x -i --threads --format --apparent-size --count-hard-links --stay-on-filesystem --ignore-dirs --log-file -h --help -V --version interactive aggregate completions help\"\n            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 1 ]] ; then\n                COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n                return 0\n            fi\n            ;;\n        dua__aggregate)\n            opts=\"-h --help\"\n            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then\n                COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n                return 0\n            fi\n            COMPREPLY=( $(compgen -f \"${{cur}}\" ) )\n            return 0\n            ;;\n        dua__completions)\n            opts=\"-h --help\"\n            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then\n                COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n                return 0\n            fi\n            COMPREPLY=( $(compgen -W \"bash elvish fish powershell zsh\" -- ${{cur}}) )\n            return 0\n            ;;\n        dua__help)\n            opts=\"-h --help\"\n            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then\n                COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n                return 0\n            fi\n            COMPREPLY=( $(compgen -W \"interactive aggregate completions\" -- ${{cur}}) )\n            return 0\n            ;;\n        dua__interactive)\n            opts=\"-h --help\"\n            if [[ ${{cur}} == -* || ${{COMP_CWORD}} -eq 2 ]] ; then\n                COMPREPLY=( $(compgen -W \"${{opts}}\" -- ${{cur}}) )\n                return 0\n            fi\n            COMPREPLY=( $(compgen -f \"${{cur}}\" ) )\n            return 0\n            ;;\n    esac\n}");
        },
        "fish" => {
            println!("complete -c dua -n '__fish_seen_subcommand_from a' -f");
        },
        "zsh" => {
            println!("#compdef dua");
        },
        "elvish" => {
            println!("# Elvish completions for dua");
        },
        "powershell" => {
            println!("# PowerShell completions for dua");
        },
        _ => {
            eprintln!("Unknown shell: {}", shell);
            std::process::exit(1);
        },
    }
    Ok(())
}
