        for (name, size) in &results {
            let formatted = format_bytes(*size, &cli.format);
            println!("{} {}", formatted.green(), name);
            total += size;
        }

        let total_formatted = format_bytes(total, &cli.format);
        println!("{} {}", total_formatted.green(), "total");
    }

    Ok(())
}

