                seen_inodes.insert(inode_key, size);
            }

            total += size;

            if entry.depth() == 1 {
                let name = path_buf.file_name()
                    .and_then(|n| n.to_str())
                    .unwrap_or("")
                    .to_string();
                entries.push((name, size));
            }
        }
    }

    // Sort by size in descending order
    entries.sort_by(|a, b| {
        match b.1.cmp(&a.1) {
            Ordering::Equal => a.0.cmp(&b.0),
            other => other,
        }
    });

    (total, entries)
}

fn run_aggregate(cli: &Cli) -> anyhow::Result<()> {
    let inputs = if cli.input.is_empty() {
        // Get all entries in current directory
        let mut entries = Vec::new();
        if let Ok(dir) = std::fs::read_dir(".") {
            for entry in dir.filter_map(Result::ok) {
                entries.push(entry.path());
            }
        }
        entries
    } else {
        cli.input.clone()
    };

    let mut ignore_dirs_set = HashSet::new();
    for dir in &cli.ignore_dirs {
        if let Ok(canonical) = dir.canonicalize() {
            ignore_dirs_set.insert(canonical);
        }
    }

    if inputs.len() == 1 {
        let path = &inputs[0];
        let (total, entries) = aggregate_path(
            path,
            cli.apparent_size,
            cli.count_hard_links,
            &ignore_dirs_set,
            cli.stay_on_filesystem,
        );

        for (name, size) in entries {
            let formatted = format_bytes(size, &cli.format);
            println!("{} {}", formatted.green(), name);
        }

        let total_formatted = format_bytes(total, &cli.format);
        println!("{} {}", total_formatted.green(), "total");
    } else {
        // Handle multiple inputs
        let mut results = Vec::new();
        for input_path in &inputs {
            let (_, entries) = aggregate_path(
                input_path,
                cli.apparent_size,
                cli.count_hard_links,
                &ignore_dirs_set,
                cli.stay_on_filesystem,
            );

            for (_, size) in entries {
                results.push((input_path.display().to_string(), size));
            }
        }

        results.sort_by(|a, b| {
            match b.1.cmp(&a.1) {
                Ordering::Equal => a.0.cmp(&b.0),
                other => other,
            }
        });

        let mut total = 0u64;
        for (name, size) in &results {
            let formatted = format_bytes(*size, &cli.format);
            println!("{} {}", formatted.green(), name);
            total += size;
        }

        let total_formatted = format_bytes(total, &cli.format);
        println!("{} {}", total_formatted.green(), "total");
    }

    Ok(())
}

fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    match &cli.command {
        Some(Commands::Interactive { input: _ }) => {
            eprintln!("Error: Interactive mode requires a connected terminal");
            std::process::exit(1);
        },
        Some(Commands::Aggregate { input: _ }) => {
            run_aggregate(&cli)?;
        },
        Some(Commands::Completions { shell }) => {
            generate_completions(shell)?;
        },
        None => {
            run_aggregate(&cli)?;
        },
    }

    Ok(())
}

