                format!("{:>9.2} MiB", mib)
            } else if bytes < 1024u64 * 1024 * 1024 * 1024 {
                let gib = bytes as f64 / (1024.0 * 1024.0 * 1024.0);
                format!("{:>9.2} GiB", gib)
            } else {
                let tib = bytes as f64 / (1024.0 * 1024.0 * 1024.0 * 1024.0);
                format!("{:>9.2} TiB", tib)
            }
        },
        "metric" => {
            if bytes == 0 {
                "     0  B".to_string()
            } else if bytes < 1000 {
                format!("{:>9}  B", bytes)
            } else if bytes < 1000 * 1000 {
                let kb = bytes as f64 / 1000.0;
                format!("{:>7.2} KB", kb)
            } else if bytes < 1000 * 1000 * 1000 {
                let mb = bytes as f64 / (1000.0 * 1000.0);
                format!("{:>7.2} MB", mb)
            } else if bytes < 1000u64 * 1000 * 1000 * 1000 {
                let gb = bytes as f64 / (1000.0 * 1000.0 * 1000.0);
                format!("{:>7.2} GB", gb)
            } else {
                let tb = bytes as f64 / (1000.0 * 1000.0 * 1000.0 * 1000.0);
                format!("{:>7.2} TB", tb)
            }
        },
        "mb" => {
            let mb = bytes as f64 / (1000.0 * 1000.0);
            format!("{:>13.2} MB", mb)
        },
        "mib" => {
            let mib = bytes as f64 / (1024.0 * 1024.0);
            format!("{:>13.2} MiB", mib)
        },
        "gb" => {
            let gb = bytes as f64 / (1000.0 * 1000.0 * 1000.0);
            format!("{:>13.2} GB", gb)
        },
        "gib" => {
            let gib = bytes as f64 / (1024.0 * 1024.0 * 1024.0);
            format!("{:>13.2} GiB", gib)
        },
        _ => format!("{}", bytes),
    }
}

fn green(s: &str) -> String {
    format!("\\x1b[32m{}\\x1b[39m", s)
}

fn get_size(metadata: &fs::Metadata, apparent_size: bool) -> u64 {
    if apparent_size {
        metadata.len()
    } else {
        metadata.blocks() as u64 * 512
    }
}

fn walk_dir_recursive(
    path: &Path,
    apparent_size: bool,
    count_hard_links: bool,
    ignore_dirs: &HashSet<PathBuf>,
    stay_on_filesystem: bool,
    seen_inodes: &mut HashMap<(u64, u64), u64>,
    results: &mut Vec<(String, u64)>,
    root_device: Option<u64>,
    depth: usize,
) -> u64 {
    let mut total = 0u64;

    let entries = match fs::read_dir(path) {
        Ok(entries) => entries.collect::<Vec<_>>(),
        Err(_) => return 0,
    };

    for entry_result in entries {
        let entry = match entry_result {
            Ok(e) => e,
            Err(_) => continue,
        };

        let entry_path = entry.path();

        if let Ok(canonical) = entry_path.canonicalize() {
            if ignore_dirs.contains(&canonical) {
                continue;
            }
        }

        let metadata = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };

        if stay_on_filesystem {
            if let Some(root_dev) = root_device {
                if metadata.dev() != root_dev {
                    continue;
                }
            }
        }

        let mut size = get_size(&metadata, apparent_size);

        if !count_hard_links && metadata.nlink() > 1 {
            let inode_key = (metadata.dev(), metadata.ino());
            if let Some(_) = seen_inodes.get(&inode_key) {
                size = 0;
            } else {
                seen_inodes.insert(inode_key, size);
            }
        } else if !count_hard_links {
            let inode_key = (metadata.dev(), metadata.ino());
            seen_inodes.insert(inode_key, size);
        }

        total += size;

        if depth == 0 {
            if let Some(name) = entry_path.file_name() {
                if let Some(name_str) = name.to_str() {
                    results.push((name_str.to_string(), size));
                }
            }
        }

        if metadata.is_dir() {
            total += walk_dir_recursive(
                &entry_path,
                apparent_size,
                count_hard_links,
                ignore_dirs,
                stay_on_filesystem,
                seen_inodes,
                results,
                root_device,
                depth + 1,
            );
        }
    }

    total
}

fn aggregate_path(
    path: &PathBuf,
    apparent_size: bool,
    count_hard_links: bool,
    ignore_dirs: &HashSet<PathBuf>,
    stay_on_filesystem: bool,
) -> (u64, Vec<(String, u64)>) {
    let metadata = match fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return (0, Vec::new()),
    };

    if metadata.is_file() {
        let size = get_size(&metadata, apparent_size);
        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_string();
        return (size, vec![(name, size)]);
    }

    let mut results = Vec::new();
    let mut seen_inodes = HashMap::new();
    let root_device = if stay_on_filesystem {
        Some(metadata.dev())
    } else {
        None
    };

    let total = walk_dir_recursive(
        path,
        apparent_size,
        count_hard_links,
        ignore_dirs,
        stay_on_filesystem,
        &mut seen_inodes,
        &mut results,
        root_device,
        0,
    );

    // Sort by size ascending, then by name
    results.sort_by(|a, b| {
        match a.1.cmp(&b.1) {
            Ordering::Equal => a.0.cmp(&b.0),
            other => other,
        }
    });

    (total, results)
}

