fn format_bytes(bytes: u64, format: &str) -> String {
    match format {
        "bytes" => format!("{:>9} b", bytes),
        "binary" => {
            if bytes == 0 {
                "      0   B".to_string()
            } else if bytes <= 1024 {
                format!("{:>7}   B", bytes)
            } else if bytes <= 1024 * 1024 {
