) -> u64 {
    let mut total = 0u64;

    let entries = match fs::read_dir(path) {
        Ok(entries) => entries.collect::<Vec<_>>(),
        Err(_) => return 0,
    };

    for entry_result in entries {
        let entry = match entry_result {
            Ok(e) => e,
            Err(_) => continue,
        };

        let entry_path = entry.path();

        if let Ok(canonical) = entry_path.canonicalize() {
            if ignore_dirs.contains(&canonical) {
                continue;
            }
        }

        let metadata = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };

        if stay_on_filesystem {
            if let Some(root_dev) = root_device {
                if metadata.dev() != root_dev {
                    continue;
                }
            }
        }

        let mut size = get_size(&metadata, apparent_size);

        if !count_hard_links && metadata.nlink() > 1 {
            let inode_key = (metadata.dev(), metadata.ino());
            if let Some(_) = seen_inodes.get(&inode_key) {
                size = 0;
            } else {
                seen_inodes.insert(inode_key, size);
            }
        } else if !count_hard_links {
            let inode_key = (metadata.dev(), metadata.ino());
            seen_inodes.insert(inode_key, size);
        }

        total += size;

        if depth == 0 {
            if let Some(name) = entry_path.file_name() {
                if let Some(name_str) = name.to_str() {
                    results.push((name_str.to_string(), size));
                }
            }
        }

        if metadata.is_dir() {
            total += walk_dir_recursive(
                &entry_path,
                apparent_size,
                count_hard_links,
                ignore_dirs,
                stay_on_filesystem,
                seen_inodes,
                results,
                root_device,
                depth + 1,
            );
        }
    }

    total
}

fn aggregate_path(
    path: &PathBuf,
    apparent_size: bool,
    count_hard_links: bool,
    ignore_dirs: &HashSet<PathBuf>,
    stay_on_filesystem: bool,
) -> (u64, Vec<(String, u64)>) {
    let metadata = match fs::metadata(path) {
        Ok(m) => m,
        Err(_) => return (0, Vec::new()),
    };

    if metadata.is_file() {
        let size = get_size(&metadata, apparent_size);
        let name = path.file_name()
            .and_then(|n| n.to_str())
            .unwrap_or("")
            .to_string();
        return (size, vec![(name, size)]);
    }

    let mut results = Vec::new();
    let mut seen_inodes = HashMap::new();
    let root_device = if stay_on_filesystem {
        Some(metadata.dev())
    } else {
        None
    };

    let total = walk_dir_recursive(
        path,
        apparent_size,
        count_hard_links,
        ignore_dirs,
        stay_on_filesystem,
        &mut seen_inodes,
        &mut results,
        root_device,
        0,
    );

    // Sort by size ascending, then by name
    results.sort_by(|a, b| {
        match a.1.cmp(&b.1) {
            Ordering::Equal => a.0.cmp(&b.0),
            other => other,
        }
    });

    (total, results)
}

fn generate_completions(shell: &str) {
    match shell {
        "bash" => {
            let bash_completion = r#"_dua() {
    local i cur prev opts cmd
    COMPREPLY=()
    if [[ "${BASH_VERSINFO[0]}" -ge 4 ]]; then
        cur="$2"
    else
        cur="${COMP_WORDS[COMP_CWORD]}"
    fi
    prev="$3"
    cmd=""
    opts=""

    for i in "${COMP_WORDS[@]:0:COMP_CWORD}"
    do
        case "${cmd},${i}" in
            ",$1")
                cmd="dua"
                ;;
            dua,a)
                cmd="dua__aggregate"
                ;;
            dua,a*)
                cmd="dua__aggregate"
                ;;
            dua,aggregate)
                cmd="dua__aggregate"
                ;;
            dua,c)
                cmd="dua__completions"
                ;;
            dua,c*)
                cmd="dua__completions"
                ;;
            dua,completions)
                cmd="dua__completions"
                ;;
            dua,help)
                cmd="dua__help"
                ;;
            dua,i)
                cmd="dua__interactive"
                ;;
            dua,i*)
                cmd="dua__interactive"
                ;;
            dua,interactive)
                cmd="dua__interactive"
                ;;
            *)
                ;;
        esac
    done

    case "${cmd}" in
        dua)
            opts="-t -f -A -l -x -i --threads --format --apparent-size --count-hard-links --stay-on-filesystem --ignore-dirs --log-file -h --help -V --version interactive aggregate completions help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 1 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
                return 0
            fi
            ;;
        dua__aggregate)
            opts="-h --help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
                return 0
            fi
            COMPREPLY=( $(compgen -f "${cur}" ) )
            return 0
            ;;
        dua__completions)
            opts="-h --help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
                return 0
            fi
            COMPREPLY=( $(compgen -W "bash elvish fish powershell zsh" -- ${cur}) )
            return 0
            ;;
        dua__help)
            opts="-h --help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
                return 0
            fi
            COMPREPLY=( $(compgen -W "interactive aggregate completions" -- ${cur}) )
            return 0
            ;;
        dua__interactive)
            opts="-h --help"
            if [[ ${cur} == -* || ${COMP_CWORD} -eq 2 ]] ; then
                COMPREPLY=( $(compgen -W "${opts}" -- ${cur}) )
                return 0
            fi
            COMPREPLY=( $(compgen -f "${cur}" ) )
            return 0
            ;;
    esac
}
"#;
            println!("{}", bash_completion);
        },
        "fish" => println!("complete -c dua -n '__fish_seen_subcommand_from a' -f"),
        "zsh" => println!("#compdef dua"),
        "elvish" => println!("# Elvish completions for dua"),
        "powershell" => println!("# PowerShell completions for dua"),
        _ => eprintln!("Unknown shell: {}", shell),
    }
}

fn parse_args() -> (Vec<PathBuf>, String, bool, bool, bool, Vec<PathBuf>, Option<String>, Option<String>) {
    let args: Vec<String> = env::args().collect();

    let mut inputs = Vec::new();
    let mut threads = 0;
    let mut format = "binary".to_string();
    let mut apparent_size = false;
    let mut count_hard_links = false;
    let mut stay_on_filesystem = false;
    let mut ignore_dirs = vec![
        PathBuf::from("/proc"),
        PathBuf::from("/dev"),
        PathBuf::from("/sys"),
        PathBuf::from("/run"),
    ];
    let mut log_file = None;
    let mut command = None;
    let mut command_arg = None;

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "--version" | "-V" => {
                println!("dua 2.32.2");
                std::process::exit(0);
            },
            "--help" | "-h" => {
                print_help();
                std::process::exit(0);
            },
            "-t" | "--threads" => {
                i += 1;
                if i < args.len() {
                    threads = args[i].parse().unwrap_or(0);
                }
            },
            "-f" | "--format" => {
                i += 1;
                if i < args.len() {
                    format = args[i].clone();
                }
            },
            "-A" | "--apparent-size" => {
                apparent_size = true;
            },
            "-l" | "--count-hard-links" => {
                count_hard_links = true;
            },
            "-x" | "--stay-on-filesystem" => {
                stay_on_filesystem = true;
            },
            "-i" | "--ignore-dirs" => {
                i += 1;
                ignore_dirs.clear();
                while i < args.len() && !args[i].starts_with('-') {
                    ignore_dirs.push(PathBuf::from(&args[i]));
                    i += 1;
                }
                i -= 1;
            },
            "--log-file" => {
                i += 1;
                if i < args.len() {
                    log_file = Some(args[i].clone());
                }
            },
            "interactive" | "i" => {
                command = Some("interactive".to_string());
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    inputs.push(PathBuf::from(&args[i]));
                    i += 1;
                }
                i -= 1;
            },
            "aggregate" | "a" => {
                command = Some("aggregate".to_string());
                i += 1;
                while i < args.len() && !args[i].starts_with('-') {
                    inputs.push(PathBuf::from(&args[i]));
                    i += 1;
                }
                i -= 1;
            },
            "completions" => {
                i += 1;
                if i < args.len() {
                    command_arg = Some(args[i].clone());
                    command = Some("completions".to_string());
                }
            },
            _ => {
                if !arg.starts_with('-') {
                    inputs.push(PathBuf::from(arg));
                }
            }
        }
        i += 1;
    }

    (inputs, format, apparent_size, count_hard_links, stay_on_filesystem, ignore_dirs, command, command_arg)
}

fn print_help() {
    println!("A tool to learn about disk usage, fast!

Usage: dua [FLAGS] [OPTIONS] [SUBCOMMAND] [INPUT]...

Commands:
  interactive  Launch the terminal user interface [aliases: i]
  aggregate    Aggregate the consumed space of one or more directories or files [aliases: a]
  completions  Generate shell completions
  help         Print this message or the help of the given subcommand(s)

Arguments:
  [INPUT]...
          One or more input files or directories. If unset, we will use all entries in the current working directory

Options:
  -t, --threads <THREADS>
          The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread

          [default: 0]

  -f, --format <FORMAT>
          The format with which to print byte counts

          [default: binary]
          [possible values: metric, binary, bytes, gb, gib, mb, mib]

  -A, --apparent-size
          Display apparent size instead of disk usage

  -l, --count-hard-links
          Count hard-linked files each time they are seen

  -x, --stay-on-filesystem
          If set, we will not cross filesystems or traverse mount points

  -i, --ignore-dirs <IGNORE_DIRS>
          One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.

          Hence, they will only be ignored if they are eventually reached as part of the traversal.

          [default: /proc /dev /sys /run]

      --log-file <LOG_FILE>
          Write a log file with debug information, including panics

  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version");
}

fn main() {
    let (inputs, format, apparent_size, count_hard_links, stay_on_filesystem, ignore_dirs, command, command_arg) = parse_args();

    match command.as_deref() {
        Some("interactive") => {
            eprintln!("Error: Interactive mode requires a connected terminal");
            std::process::exit(1);
        },
        Some("completions") => {
            if let Some(shell) = command_arg {
                generate_completions(&shell);
            }
        },
        _ => {
            let final_inputs = if inputs.is_empty() {
                vec![PathBuf::from(".")]
            } else {
                inputs
            };

            let mut ignore_dirs_set = HashSet::new();
            for dir in &ignore_dirs {
                if let Ok(canonical) = dir.canonicalize() {
                    ignore_dirs_set.insert(canonical);
                }
            }

            if final_inputs.len() == 1 {
                let path = &final_inputs[0];
                let (total, entries) = aggregate_path(
                    path,
                    apparent_size,
                    count_hard_links,
                    &ignore_dirs_set,
                    stay_on_filesystem,
                );

                for (name, size) in entries {
                    let formatted = format_bytes(size, &format);
                    println!("{} {}", green(&formatted), name);
                }

                let total_formatted = format_bytes(total, &format);
                println!("{} {}", green(&total_formatted), "total");
            } else if final_inputs.len() > 1 {
                let mut results = Vec::new();
                for input_path in &final_inputs {
                    let (_, entries) = aggregate_path(
                        input_path,
                        apparent_size,
                        count_hard_links,
                        &ignore_dirs_set,
                        stay_on_filesystem,
                    );

                    for (_, size) in entries {
                        results.push((input_path.display().to_string(), size));
                    }
                }

                results.sort_by(|a, b| {
                    match a.1.cmp(&b.1) {
                        Ordering::Equal => a.0.cmp(&b.0),
                        other => other,
                    }
                });

                let mut total = 0u64;
                for (name, size) in &results {
                    let formatted = format_bytes(*size, &format);
                    println!("{} {}", green(&formatted), name);
                    total += size;
                }

                let total_formatted = format_bytes(total, &format);
                println!("{} {}", green(&total_formatted), "total");
            }
        },
    }
}
